[et_pb_section fb_built="1" admin_label="RM E-commerce Hero" _builder_version="4.27.4" use_custom_width="on" width_unit="off" custom_width_px="100%" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_row _builder_version="4.27.4" width="100%" max_width="100%" use_custom_gutter="on" gutter_width="1" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_column type="4_4" _builder_version="4.27.4" global_colors_info="{}"][et_pb_code admin_label="RM E-commerce Hero — Code" _builder_version="4.27.4" global_colors_info="{}"]<!-- ============================================================
     RM E-COMMERCE HERO — Sección hero para la página de Tienda Online
     (Divi 5, Code Module)
     Marca: Rodmedia (hub de servicios gestionados — ver BRAND.md)

     Sistema de marca cerrado (no reinterpretar), igual que rm-hero-home.html:
     - Fondo navy #0f0f1e
     - Partículas en canvas con líneas de conexión azules
     - Gradientes de luz animados azul #3a7bd5 + naranja #e8531a
     - Tipografía Playfair Display (titulares) + Inter (cuerpo)
     - Línea superior de firma con gradiente animado
     - Entradas secuenciadas con fade + slide-up
     - Badge con parpadeo sutil
     Visual propio de esta página: showcase de producto en 3D real (CSS
     3D transforms + perspective) — 3 tarjetas apiladas en profundidad,
     la frontal se inclina siguiendo el cursor (tilt) con vaivén suave
     cuando no hay interacción, más una insignia flotante de "nuevo
     pedido". Sustituye al mockup plano de la versión anterior.

     ANTES DE PUBLICAR:
     1) Sustituye las cifras de "rm-ec-hero__stats" por datos reales.
     2) Revisa el enlace de WhatsApp (wa.me) y el ancla #rmec-planes.
     3) Si ya cargas Playfair Display / Inter en otra sección de la
        misma página, borra el @import de aquí.
     ============================================================ -->

<section class="rm-ec-hero" aria-label="Tienda online — Rodmedia">

  <div class="rm-ec-hero__bg" aria-hidden="true">
    <div class="rm-ec-hero__topline"></div>
    <canvas class="rm-ec-hero__particles"></canvas>
    <div class="rm-ec-hero__glow rm-ec-hero__glow--blue"></div>
    <div class="rm-ec-hero__glow rm-ec-hero__glow--orange"></div>
  </div>

  <div class="rm-ec-hero__container">

    <div class="rm-ec-hero__content" data-animate>
      <span class="rm-ec-hero__chip">
        <span class="rm-ec-hero__chip-dot" aria-hidden="true"></span>
        Tu mostrador abierto las 24 horas
      </span>

      <h1 class="rm-ec-hero__title">
        Tu tienda online lista para <em>vender desde</em> el primer día
      </h1>

      <p class="rm-ec-hero__subtitle">
        Convertimos tu negocio físico en una tienda global que trabaja
        mientras tú duermes. WooCommerce, diseño a medida y pasarelas de
        pago, todo listo para vender sin complicaciones técnicas.
      </p>

      <div class="rm-ec-hero__insight">
        <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
          <path d="M2.5 4.5h2l1.6 8.2a1.4 1.4 0 0 0 1.4 1.1h6a1.4 1.4 0 0 0 1.4-1.1l1.1-5.7H5.3" stroke="var(--rm-blue)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          <circle cx="8" cy="16" r="1" fill="var(--rm-blue)"/>
          <circle cx="13.5" cy="16" r="1" fill="var(--rm-blue)"/>
        </svg>
        <p>
          El <strong>76% de los españoles compra online</strong>. Si no
          tienes tienda, estás regalando ventas a tu competencia.
        </p>
      </div>

      <div class="rm-ec-hero__actions">
        <a href="https://wa.me/34691306858" target="_blank" rel="noopener" class="rm-ec-hero__cta rm-ec-hero__cta--primary">
          <span>Quiero mi tienda online</span>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M3.5 8h9M8.5 3.5 13 8l-4.5 4.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </a>
        <a href="#rmec-planes" class="rm-ec-hero__cta rm-ec-hero__cta--secondary">
          Ver planes y precios
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
            <path d="M3 5.5 7 9.5l4-4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </a>
      </div>

      <dl class="rm-ec-hero__stats">
        <div class="rm-ec-hero__stat">
          <dt>890€</dt>
          <dd>desde pago único</dd>
        </div>
        <div class="rm-ec-hero__stat">
          <dt>20</dt>
          <dd>productos incluidos</dd>
        </div>
        <div class="rm-ec-hero__stat">
          <dt>24/7</dt>
          <dd>vendiendo sola</dd>
        </div>
        <div class="rm-ec-hero__stat">
          <dt>100%</dt>
          <dd>tuya siempre</dd>
        </div>
      </dl>
    </div>

    <div class="rm-ec-hero__visual" data-animate>
      <div class="rm-ec-hero__stage">
        <div class="rm-ec-hero__card rm-ec-hero__card--back"></div>
        <div class="rm-ec-hero__card rm-ec-hero__card--mid"></div>
        <div class="rm-ec-hero__card rm-ec-hero__card--front">
          <span class="rm-ec-hero__card-sheen" aria-hidden="true"></span>
          <span class="rm-ec-hero__card-badge">Más vendido</span>
          <span class="rm-ec-hero__card-img" aria-hidden="true"></span>
          <div class="rm-ec-hero__card-info">
            <span class="rm-ec-hero__card-name">Edición limitada</span>
            <div class="rm-ec-hero__card-row">
              <strong class="rm-ec-hero__card-price">43,90€</strong>
              <span class="rm-ec-hero__card-add" aria-hidden="true">
                <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><path d="M7 2.5v9M2.5 7h9" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
              </span>
            </div>
          </div>

          <span class="rm-ec-hero__add-feedback" aria-hidden="true">Añadido ✓</span>

          <span class="rm-ec-hero__cursor" aria-hidden="true">
            <span class="rm-ec-hero__cursor-ring"></span>
            <svg viewBox="0 0 24 24" fill="none"><path d="M5 3.2 19 10l-6.2 2-2 6.2L5 3.2Z" fill="#ffffff" stroke="#0f0f1e" stroke-width="1.1" stroke-linejoin="round"/></svg>
          </span>
        </div>
      </div>

      <div class="rm-ec-hero__order-badge">
        <span class="rm-ec-hero__order-dot" aria-hidden="true"></span>
        <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
          <path d="M2.5 4.5h2l1.6 8.2a1.4 1.4 0 0 0 1.4 1.1h6a1.4 1.4 0 0 0 1.4-1.1l1.1-5.7H5.3" stroke="var(--rm-blue)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          <circle cx="8" cy="16" r="1" fill="var(--rm-blue)"/>
          <circle cx="13.5" cy="16" r="1" fill="var(--rm-blue)"/>
        </svg>
        <div>
          <strong>Nuevo pedido</strong>
          <span>hace 2 min · 43,90€</span>
        </div>
      </div>
    </div>

  </div>
</section>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Inter:wght@400;500;600;700&display=swap');

  .rm-ec-hero {
    --rm-primary: #0f0f1e;
    --rm-blue: #3a7bd5;
    --rm-orange: #e8531a;
    --rm-light: #f8f8fb;
    --rm-text: var(--rm-light);
    --rm-text-muted: #9aa3bd;
    --rm-text-muted-2: #7d84a0;
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    --rm-transition: 0.3s ease;
    --rm-font-display: "Playfair Display", Georgia, "Times New Roman", serif;
    --rm-font-body: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: var(--rm-primary);
    color: var(--rm-text);
    font-family: var(--rm-font-body);
    padding: 120px 20px 100px;
    box-sizing: border-box;
  }

  .rm-ec-hero *,
  .rm-ec-hero *::before,
  .rm-ec-hero *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo decorativo ---------- */
  .rm-ec-hero__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
  }

  .rm-ec-hero__topline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--rm-blue), var(--rm-orange), var(--rm-blue));
    background-size: 200% 100%;
    animation: rm-ec-hero-shimmer 6s linear infinite;
  }

  @keyframes rm-ec-hero-shimmer {
    0% { background-position: 0% 0; }
    100% { background-position: 200% 0; }
  }

  .rm-ec-hero__particles {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
  }

  .rm-ec-hero__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.28;
    animation: rm-ec-hero-float 15s ease-in-out infinite;
  }

  .rm-ec-hero__glow--blue {
    width: 480px;
    height: 480px;
    top: -150px;
    right: -110px;
    background: var(--rm-blue);
  }

  .rm-ec-hero__glow--orange {
    width: 420px;
    height: 420px;
    bottom: -170px;
    left: -110px;
    background: var(--rm-orange);
    animation-delay: -7s;
  }

  @keyframes rm-ec-hero-float {
    0%, 100% { transform: translate(0, 0) scale(1); }
    50% { transform: translate(26px, 22px) scale(1.07); }
  }

  /* ---------- Contenedor ---------- */
  .rm-ec-hero__container {
    position: relative;
    z-index: 1;
    max-width: 1140px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    align-items: center;
    gap: 64px;
  }

  .rm-ec-hero__content[data-animate],
  .rm-ec-hero__visual[data-animate] {
    opacity: 0;
    transform: translateY(24px);
    transition: opacity 0.7s ease, transform 0.7s ease;
  }

  .rm-ec-hero__content.is-visible,
  .rm-ec-hero__visual.is-visible {
    opacity: 1;
    transform: translateY(0);
  }

  .rm-ec-hero__visual[data-animate] {
    transition-delay: 0.15s;
  }

  /* ---------- Chip con pulso ---------- */
  .rm-ec-hero__chip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #cbd5e1;
    margin-bottom: 24px;
  }

  .rm-ec-hero__chip-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    animation: rm-ec-hero-blink 2.2s ease-in-out infinite;
  }

  @keyframes rm-ec-hero-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.25; }
  }

  /* ---------- Titular ---------- */
  .rm-ec-hero__title {
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: clamp(2.25rem, 1.4rem + 3.4vw, 3.75rem);
    line-height: 1.14;
    letter-spacing: -0.01em;
    margin: 0 0 20px;
    color: var(--rm-light);
  }

  .rm-ec-hero__title em {
    font-style: italic;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .rm-ec-hero__subtitle {
    font-size: 17px;
    line-height: 1.7;
    color: var(--rm-text-muted);
    max-width: 48ch;
    margin: 0 0 28px;
  }

  /* ---------- Insight de credibilidad ---------- */
  .rm-ec-hero__insight {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 16px 20px;
    margin-bottom: 36px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: var(--rm-radius-lg);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    max-width: 48ch;
  }

  .rm-ec-hero__insight svg {
    flex-shrink: 0;
    margin-top: 2px;
  }

  .rm-ec-hero__insight p {
    margin: 0;
    font-size: 14px;
    line-height: 1.6;
    color: var(--rm-text-muted);
  }

  .rm-ec-hero__insight strong {
    color: var(--rm-light);
    font-weight: 600;
  }

  /* ---------- CTAs ---------- */
  .rm-ec-hero__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 20px;
    margin-bottom: 48px;
  }

  .rm-ec-hero__cta {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--rm-font-body);
    font-size: 15px;
    font-weight: 600;
    text-decoration: none;
    border-radius: var(--rm-radius);
    transition: transform var(--rm-transition), box-shadow var(--rm-transition),
      border-color var(--rm-transition), color var(--rm-transition);
    overflow: hidden;
  }

  .rm-ec-hero__cta--primary {
    padding: 16px 28px;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #ffffff;
    box-shadow: 0 12px 28px rgba(58, 123, 213, 0.28);
  }

  .rm-ec-hero__cta--primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(160px circle at var(--rm-mx, 50%) var(--rm-my, 50%), rgba(255, 255, 255, 0.32), transparent 70%);
    opacity: 0;
    transition: opacity var(--rm-transition);
  }

  .rm-ec-hero__cta--primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 34px rgba(232, 83, 26, 0.35);
  }

  .rm-ec-hero__cta--primary:hover::before {
    opacity: 1;
  }

  .rm-ec-hero__cta--primary span,
  .rm-ec-hero__cta--primary svg {
    position: relative;
    z-index: 1;
  }

  .rm-ec-hero__cta--secondary {
    padding: 16px 4px;
    color: var(--rm-light);
    border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  }

  .rm-ec-hero__cta--secondary:hover {
    border-color: var(--rm-blue);
    color: var(--rm-light);
  }

  /* ---------- Franja de stats ---------- */
  .rm-ec-hero__stats {
    display: flex;
    flex-wrap: wrap;
    margin: 0;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--rm-radius-lg);
    background: rgba(255, 255, 255, 0.025);
    overflow: hidden;
    max-width: 560px;
  }

  .rm-ec-hero__stat {
    flex: 1 1 0;
    min-width: 120px;
    padding: 18px 16px;
    text-align: center;
    border-right: 1px solid rgba(255, 255, 255, 0.08);
  }

  .rm-ec-hero__stat:last-child {
    border-right: none;
  }

  .rm-ec-hero__stat dt {
    font-family: var(--rm-font-display);
    font-size: 22px;
    font-weight: 600;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    margin: 0 0 4px;
  }

  .rm-ec-hero__stat dd {
    margin: 0;
    font-size: 11px;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: var(--rm-text-muted-2);
  }

  /* ---------- Visual: showcase 3D ---------- */
  .rm-ec-hero__visual {
    position: relative;
    width: 100%;
  }

  .rm-ec-hero__stage {
    position: relative;
    width: 100%;
    max-width: 400px;
    aspect-ratio: 1 / 1;
    margin: 0 auto;
    perspective: 1400px;
  }

  .rm-ec-hero__card {
    position: absolute;
    inset: 8%;
    border-radius: var(--rm-radius-lg);
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }

  .rm-ec-hero__card--back {
    transform: translate(46px, 40px) translateZ(-120px) rotate(9deg) scale(0.88);
    opacity: 0.4;
  }

  .rm-ec-hero__card--mid {
    transform: translate(23px, 20px) translateZ(-60px) rotate(4.5deg) scale(0.94);
    opacity: 0.7;
  }

  .rm-ec-hero__card--front {
    box-shadow: var(--rm-shadow);
    overflow: hidden;
    animation: rm-ec-hero-idle-sway 7s ease-in-out infinite;
    transition: transform 0.15s ease-out;
    will-change: transform;
  }

  .rm-ec-hero__stage.is-interactive .rm-ec-hero__card--front {
    animation: none;
  }

  @keyframes rm-ec-hero-idle-sway {
    0%, 100% { transform: rotateY(-5deg) rotateX(2.5deg); }
    50% { transform: rotateY(5deg) rotateX(-2.5deg); }
  }

  .rm-ec-hero__card-sheen {
    position: absolute;
    inset: -40%;
    background: linear-gradient(115deg, transparent 40%, rgba(255, 255, 255, 0.16) 50%, transparent 60%);
    opacity: 0.5;
    pointer-events: none;
    transition: opacity 0.3s ease;
  }

  .rm-ec-hero__stage.is-interactive .rm-ec-hero__card-sheen {
    opacity: 0.9;
  }

  .rm-ec-hero__card-badge {
    position: absolute;
    top: 16px;
    left: 16px;
    padding: 5px 12px;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 1;
  }

  .rm-ec-hero__card-img {
    position: absolute;
    inset: 0 0 34% 0;
    background:
      radial-gradient(120% 90% at 20% 15%, rgba(255, 255, 255, 0.16), transparent 55%),
      linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
  }

  .rm-ec-hero__card-info {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 34%;
    padding: 14px 18px 16px;
    background: rgba(12, 12, 24, 0.55);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
  }

  .rm-ec-hero__card-name {
    font-size: 13px;
    font-weight: 500;
    color: var(--rm-text-muted);
  }

  .rm-ec-hero__card-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .rm-ec-hero__card-price {
    font-family: var(--rm-font-display);
    font-size: 20px;
    font-weight: 700;
    color: var(--rm-light);
  }

  .rm-ec-hero__card-add {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #fff;
    animation: rm-ec-hero-add-press 6s ease-in-out infinite;
  }

  @keyframes rm-ec-hero-add-press {
    0%, 44% { transform: scale(1); }
    48% { transform: scale(0.8); }
    54% { transform: scale(1.14); }
    60%, 100% { transform: scale(1); }
  }

  /* ---------- Demo animada: "alguien está comprando ahora" ---------- */
  .rm-ec-hero__add-feedback {
    position: absolute;
    right: 18px;
    bottom: 58px;
    z-index: 2;
    padding: 5px 10px;
    border-radius: 999px;
    background: rgba(15, 15, 30, 0.85);
    border: 1px solid rgba(58, 123, 213, 0.4);
    color: var(--rm-light);
    font-size: 11px;
    font-weight: 600;
    white-space: nowrap;
    opacity: 0;
    transform: translateY(6px) scale(0.92);
    animation: rm-ec-hero-feedback-pop 6s ease-in-out infinite;
  }

  @keyframes rm-ec-hero-feedback-pop {
    0%, 50% { opacity: 0; transform: translateY(6px) scale(0.92); }
    56% { opacity: 1; transform: translateY(0) scale(1); }
    74% { opacity: 1; transform: translateY(0) scale(1); }
    84%, 100% { opacity: 0; transform: translateY(-6px) scale(0.95); }
  }

  .rm-ec-hero__cursor {
    position: absolute;
    left: 32%;
    top: 58%;
    width: 20px;
    height: 20px;
    z-index: 3;
    pointer-events: none;
    opacity: 0;
    filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.45));
    animation: rm-ec-hero-cursor-move 6s ease-in-out infinite;
  }

  .rm-ec-hero__cursor svg {
    width: 100%;
    height: 100%;
    display: block;
  }

  .rm-ec-hero__cursor-ring {
    position: absolute;
    top: 2px;
    left: 1px;
    width: 13px;
    height: 13px;
    border-radius: 50%;
    border: 2px solid var(--rm-blue);
    opacity: 0;
    animation: rm-ec-hero-cursor-ring 6s ease-in-out infinite;
  }

  @keyframes rm-ec-hero-cursor-move {
    0%   { left: 32%; top: 58%; opacity: 0; transform: scale(1); }
    8%   { opacity: 1; }
    40%  { left: 84%; top: 84%; opacity: 1; transform: scale(1); }
    48%  { left: 84%; top: 84%; opacity: 1; transform: scale(0.82); }
    54%  { left: 84%; top: 84%; opacity: 1; transform: scale(1); }
    82%  { left: 84%; top: 84%; opacity: 1; transform: scale(1); }
    92%  { opacity: 0; }
    100% { left: 32%; top: 58%; opacity: 0; transform: scale(1); }
  }

  @keyframes rm-ec-hero-cursor-ring {
